/* ==============================
   pi Hub — x.ai inspired light theme
   ============================== */

:root {
  /* Surfaces */
  --canvas: #f8f8fa;
  --surface: #f0f0f3;
  --surface-raised: #ffffff;
  --surface-subtle: #ebebee;

  /* Borders */
  --border: rgba(0, 0, 0, 0.06);
  --border-strong: rgba(0, 0, 0, 0.10);

  /* Text */
  --text: #111113;
  --text-body: #4b4b55;
  --muted: #8e8e98;


