/* =================================
   Chat Layout
   ================================= */

.chat-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  height: 100%;
  position: relative;
}

.sidebar-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 40;
  background: rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity var(--duration-fast) ease;
  pointer-events: none;
}

.sidebar-backdrop.visible {
  opacity: 1;
  pointer-events: auto;
}

.sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border);
  background: var(--surface);
  overflow-y: auto;
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: transform var(--duration-normal) var(--ease-out);
}

.sidebar-section {
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.4rem 0.5rem;
  background: transparent;
  border-bottom: 1px solid var(--border);
  animation: fade-up var(--duration-normal) var(--ease-out) both;
}

.sidebar-section:nth-child(1) { animation-delay: 0.04s; }
.sidebar-section:nth-child(2) { animation-delay: 0.08s; }
.sidebar-section:nth-child(3) { animation-delay: 0.12s; }
.sidebar-section:nth-child(4) { animation-delay: 0.16s; }

.sidebar-section summary {
  cursor: pointer;
  font-weight: 500;
  color: var(--text);
  padding: 0.5rem 0.35rem;
  border-radius: var(--radius-sm);
